item.content:encoded:
.elementor-section.elementor-section.elementor-section-boxed>.elementor-container {
    max-width: 1140px;
}

span.mega-indicator {
    float: right;
}

.fa-map-marker:before {
    content: "\f041" !important;
}

.widget_product_search .woocommerce-product-search button:before {
    color: #333;
}

.reign-header-top {
	  font-size: 13px;
    padding: 10px 0;
}
.version-four .widget_product_search .woocommerce-product-search .search-field {
    padding-right: 30px;
    border: none;
    border-radius: 0;
}
.version-four .widget_product_search .woocommerce-product-search button {
    top: 0;
    right: 0;
    width: 35px;
    height: 38px;
    background: #E16E25;
    line-height: 38px;
}
.version-four .rg-hdr-v4-row-2 {
    background: transparent;
    text-align: center;
    border-top: 1px solid  rgba(255,255,255,0.1)
}
.version-four .widget_product_search .woocommerce-product-search button:before {
    color: #fff;
}
.reign-header-top .container {
    max-width: 1150px;
}
.sub-menu a {
    text-align: left !important;
}

.elementor-section.elementor-section.elementor-section-boxed>.elementor-container {
    max-width: 1140px;
}

span.mega-indicator {
    float: right;
}

.fa-map-marker:before {
    content: "\f041" !important;
}

.widget_product_search .woocommerce-product-search button:before {
    color: #333;
}

.reign-header-top {
	  font-size: 13px;
    padding: 10px 0;
}

